package mz.bam.seeky.android;
import java.net.URLEncoder;import java.util.*;
/** Link only visible text nodes; markup, existing links and book scripts stay untouched. */
final class BibleHtml {
 static String link(String html){StringBuilder out=new StringBuilder(html.length());int at=0;while(at<html.length()){int tag=html.indexOf('<',at);if(tag<0)tag=html.length();String text=html.substring(at,tag).replaceAll("(?i)&(?:nbsp|#0*160|#x0*a0);","\u00a0").replaceAll("(?i)&#(?:0*58|x0*3a);",":");List<BibleReferences.Reference> refs=BibleReferences.references(text);int p=0;for(BibleReferences.Reference r:refs){out.append(text,p,r.start);try{out.append("<a class=\"seeky-bible-reference\" style=\"color:inherit;text-decoration:underline\" href=\"seekybible://passage?ref=").append(URLEncoder.encode(r.label,"UTF-8")).append("\">").append(text,r.start,r.end).append("</a>");}catch(java.io.UnsupportedEncodingException e){throw new IllegalStateException(e);}p=r.end;}out.append(text,p,text.length());if(tag==html.length())break;boolean comment=html.startsWith("<!--",tag);int end=comment?html.indexOf("-->",tag+4):tagEnd(html,tag+1);if(end<0){out.append(html,tag,html.length());break;}if(comment)end+=2;String raw=html.substring(tag,end+1),name=raw.replaceFirst("^<\\s*/?\\s*","").split("[\\s/>]",2)[0].toLowerCase(Locale.ROOT);if(!comment&&!raw.matches("(?s)^<\\s*/.*")&&!raw.endsWith("/>")&&Arrays.asList("a","script","style","head","title","svg","math","pre","code").contains(name)){java.util.regex.Matcher close=java.util.regex.Pattern.compile("(?i)</"+name+"\\s*>").matcher(html);if(close.find(end+1))end=close.end()-1;else end=html.length()-1;}out.append(html,tag,end+1);at=end+1;}return out.toString();}
 static int tagEnd(String html,int at){char quote=0;for(int i=at;i<html.length();i++){char c=html.charAt(i);if(quote!=0){if(c==quote)quote=0;}else if(c=='\''||c=='"')quote=c;else if(c=='>')return i;}return -1;}
 private BibleHtml(){}
}
